CREATE OR REPLACE PROCEDURE sp(
    para_Age NUMBER,
    para_Name VARCHAR2,
    para_Party VARCHAR2,
    para_Home_city VARCHAR2
) AS
    CURSOR driver_cur IS
        SELECT * FROM driver WHERE Age > para_Age AND Party = para_Party;
BEGIN
    FOR rec IN driver_cur LOOP
        UPDATE driver SET Name = para_Name WHERE Driver_ID = rec.Driver_ID;
    END LOOP;
    DELETE FROM driver WHERE Party IS NULL;
    UPDATE driver SET Home_city = para_Home_city;
    UPDATE school_bus pt
       SET Years_Working = Years_Working + 1
     WHERE pt.Driver_ID IN (SELECT d.Driver_ID FROM driver d);
END;

